#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 64

typedef struct {
    long value;
    int left;
    int right;
} Node;

static Node nodes[MAX_NODES];
static int root = -1;
static int used = 0;

static int insert_value(long v) {
    if (used >= MAX_NODES) return -1;
    if (root == -1) {
        nodes[used].value = v;
        nodes[used].left = nodes[used].right = -1;
        root = used;
        ++used;
        return 0;
    }
    int cur = root;
    while (1) {
        if (v < nodes[cur].value) {
            if (nodes[cur].left == -1) {
                nodes[used].value = v;
                nodes[used].left = nodes[used].right = -1;
                nodes[cur].left = used;
                ++used;
                return 0;
            }
            cur = nodes[cur].left;
        } else {
            if (nodes[cur].right == -1) {
                nodes[used].value = v;
                nodes[used].left = nodes[used].right = -1;
                nodes[cur].right = used;
                ++used;
                return 0;
            }
            cur = nodes[cur].right;
        }
    }
}

static void inorder(int idx, int *printed) {
    if (idx == -1) return;
    inorder(nodes[idx].left, printed);
    if (*printed) putchar(' ');
    printf("%ld", nodes[idx].value);
    *printed = 1;
    inorder(nodes[idx].right, printed);
}

static void preorder(int idx, int *printed) {
    if (idx == -1) return;
    if (*printed) putchar(' ');
    printf("%ld", nodes[idx].value);
    *printed = 1;
    preorder(nodes[idx].left, printed);
    preorder(nodes[idx].right, printed);
}

static void postorder(int idx, int *printed) {
    if (idx == -1) return;
    postorder(nodes[idx].left, printed);
    postorder(nodes[idx].right, printed);
    if (*printed) putchar(' ');
    printf("%ld", nodes[idx].value);
    *printed = 1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("INVALID_MODE");
        return 0;
    }
    const char *mode = argv[1];
    if (strcmp(mode, "in") != 0 && strcmp(mode, "pre") != 0 && strcmp(mode, "post") != 0) {
        puts("INVALID_MODE");
        return 0;
    }
    for (int i = 2; i < argc && used < MAX_NODES; ++i) {
        char *endptr;
        long v = strtol(argv[i], &endptr, 10);
        (void)endptr;
        insert_value(v);
    }
    if (root == -1) {
        puts("EMPTY");
        return 0;
    }
    int printed = 0;
    if (strcmp(mode, "in") == 0) {
        inorder(root, &printed);
    } else if (strcmp(mode, "pre") == 0) {
        preorder(root, &printed);
    } else {
        postorder(root, &printed);
    }
    putchar('\n');
    return 0;
}
